const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const main = $('#main');
$('.skip-link').addEventListener('click',event=>{event.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({block:'start'});});
let data, staff, staffTab='dashboard', filter={date:'',discipline:'',coach:''}, draft={}, attempt, routeVersion=0;
const e = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro = n => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:n%100?2:0}).format(n/100);
const date = (s,options={}) => new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',day:'numeric',month:'long',...options}).format(new Date(s));
const time = s => new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',hour:'2-digit',minute:'2-digit'}).format(new Date(s));
const dateKey = s => new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(s));
const fullDate = s => date(s,{weekday:'long',year:'numeric'});
const stateLabels={pending:'En attente',confirmed:'Confirmée',cancelled:'Annulée',expired:'Expirée',succeeded:'Réussi (simulation)',declined:'Refusé (simulation)',refunded:'Remboursé (simulation)'};
const roleLabels={admin:'Administrateur',accueil:'Accueil',coach:'Coach'};
const arrow='<span aria-hidden="true">↗</span>';
const imageMap={'Musculation encadrée':'strength','HIIT':'strength','Cycling':'cycling','Mobilité':'mobility','Circuit training':'hero','Coaching individuel':'strength'};
async function api(path,options={}) {
  const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});
  const json=await response.json(); if(!response.ok) throw new Error(json.error||'La connexion a échoué. Réessayez.'); return json;
}
const post=(path,body={})=>api(path,{method:'POST',body});
const patch=(path,body)=>api(path,{method:'PATCH',body});
function track(type) { post('/api/events',{type}).catch(()=>{}); }
function toast(message) { const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,6500); }
async function confirmAction(message) {
  const dialog=$('#confirm-dialog');$('#confirm-message').textContent=message;dialog.returnValue='';dialog.showModal();
  return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true}));
}
function title(heading,kicker='',copy='') { return `<section class="page-heading container">${kicker?`<span class="eyebrow">${kicker}</span>`:''}<h1>${heading}</h1>${copy?`<p>${copy}</p>`:''}</section>`; }
const notice=(message,kind='info')=>`<div class="notice ${kind}" role="${kind==='error'?'alert':'status'}">${message}</div>`;
const loading=()=>'<div class="container loading" role="status">Chargement en cours…</div>';
function badge(c) {
  if(c.status==='cancelled') return '<span class="badge muted">Annulée</span>';
  if(c.remaining<=0) return '<span class="badge muted">Complet</span>';
  if(c.remaining<=3) return `<span class="badge warning">${c.remaining} place${c.remaining>1?'s':''} restante${c.remaining>1?'s':''}</span>`;
  return `<span class="badge">${c.remaining} places disponibles</span>`;
}
function sessionRow(c,compact=false) {
  const active=c.status!=='cancelled'&&c.remaining>0;
  return `<article class="session-row ${active?'':'unavailable'}"><div class="session-date"><strong>${date(c.starts,{day:'2-digit',month:undefined})}</strong><span>${date(c.starts,{month:'short',day:undefined})}</span></div><div class="session-info"><span class="session-category">${c.level} · ${c.duration} min</span><h3><a href="#/seance/${c.id}">${e(c.discipline)}</a></h3><p>${compact?'':`${date(c.starts,{weekday:'short'})} · `}${time(c.starts)} <span class="dot-separator">/</span> ${e(c.coach)}</p></div><div class="session-stock">${badge(c)}<span>${euro(c.price)} / séance</span></div>${active?`<a class="button ${compact?'secondary':'small'}" href="#/seance/${c.id}">Réserver ${arrow}</a>`:`<button class="button secondary small" disabled>${c.status==='cancelled'?'Annulée':'Complet'}</button>`}</article>`;
}
function offers() {
  return `<div class="offer-grid">${data.offers.map((o,i)=>`<article class="offer ${i===0?'featured':''}"><div class="offer-top"><span class="eyebrow">${['Pour commencer','Pour garder le rythme','Pour aller plus loin'][i]}</span>${i===0?'<span class="badge">En ligne</span>':''}</div><h3>${e(o.name)}</h3><p class="price">${euro(o.price)}<span>${i===1?'/ 10 séances':i===2?'/ 60 min':'/ séance'}</span></p><p>${e(o.description)}</p><ul class="check-list">${(i===0?['Toutes les disciplines collectives','Matériel de salle inclus','Sans création de compte']:i===1?['12 € par séance','Valable 6 mois (démonstration)','Achat sur demande']:['Accompagnement personnalisé','Un créneau adapté à vos objectifs','Réservation sur demande']).map(x=>`<li>${x}</li>`).join('')}</ul><p class="offer-conditions">${e(o.conditions)}</p><a href="${o.bookable?'#/planning':`#/contact?offre=${o.id}`}" class="button ${i===0?'':'secondary'}">${o.bookable?'Choisir ma séance':'Me renseigner'} ${arrow}</a></article>`).join('')}</div>`;
}
function faq() {
  return `<div class="faq-list">${[
    ['Je débute, est-ce fait pour moi ?','Oui. Les séances « Tous niveaux » proposent des variantes adaptées. Présentez-vous quelques minutes avant le début du cours pour échanger avec votre coach.'],
    ['Faut-il créer un compte pour réserver ?','Non. Choisissez votre séance, renseignez votre prénom, votre nom et votre e-mail, puis terminez le paiement de démonstration. Un lien personnel vous permet ensuite de gérer votre réservation.'],
    ['Puis-je annuler ma séance ?','Vous pouvez annuler jusqu’à 24 heures avant le début. Le remboursement intégral est alors simulé et la place est libérée. Après ce délai, aucun remboursement n’est prévu.'],
    ['Que dois-je apporter ?','Prévoyez une tenue de sport, des chaussures propres, une serviette et une gourde. Le matériel spécifique est indiqué sur chaque fiche de séance.'],
    ['Le paiement est-il réel ?','Non. Ce site est une démonstration : aucun prélèvement, aucune carte bancaire demandée et aucun e-mail envoyé. Utilisez uniquement des coordonnées fictives.']
  ].map(([q,a],i)=>`<details><summary><span class="faq-index">0${i+1}</span>${q}<span class="faq-plus" aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div>`;
}
function home() {
  const next=data.classes.filter(c=>c.status!=='cancelled'&&c.remaining>0).slice(0,3);
  return `<section class="hero container"><div class="hero-copy"><div class="eyebrow"><span class="mini-line"></span> Salle de sport & coaching</div><h1>VOTRE PROCHAIN<br>MOUVEMENT<br>COMMENCE <span class="highlight">ICI<span class="headline-dot">.</span></span></h1><p>De l’énergie, du collectif, et un coach pour avancer.<br class="desktop-only"> Trouvez votre séance. On s’occupe du reste.</p><div class="actions"><a href="#/planning" class="button">Réserver une séance ${arrow}</a><a href="#/offres" class="text-link">Découvrir les offres <span aria-hidden="true">→</span></a></div><div class="hero-footnote"><span class="outline-icon" aria-hidden="true">◷</span><span>Votre planning accessible 24 h/24.<br><strong>Votre place réservée en quelques clics.</strong></span></div></div><div class="hero-visual"><img src="/assets/hero.jpg" alt="Plateau de musculation avec haltères et équipements d’entraînement, photographie d’illustration" fetchpriority="high" width="1400" height="1000"><div class="image-caption"><span>UN PEU D’EFFORT.<br>BEAUCOUP D’ÉLAN.</span><span class="image-arrow" aria-hidden="true">↗</span></div><div class="image-label"><span class="live-dot"></span> À votre rythme. Ensemble.</div></div><div class="hero-side-label" aria-hidden="true">BOUGER. PROGRESSER. RECOMMENCER.</div></section>
  <div class="benefit-strip"><div class="container"><span><span aria-hidden="true">↗</span> Réservation sans compte</span><span><span aria-hidden="true">◷</span> Des créneaux toute la semaine</span><span><span aria-hidden="true">◎</span> Des coachs à vos côtés</span><span><span aria-hidden="true">✓</span> À partir de ${euro(data.offers[0].price)} la séance</span></div></div>
  <section class="section container next-sessions"><div class="section-heading"><div><span class="eyebrow">À vous de jouer</span><h2>Le prochain départ,<br>c’est le vôtre.</h2></div><a class="text-link" href="#/planning">Tout le planning ${arrow}</a></div><div class="session-list">${next.map(c=>sessionRow(c,true)).join('')}</div><p class="subtle small-print">Horaires en heure de Paris. Disponibilités actualisées à chaque consultation.</p></section>
  <section class="section disciplines-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Trouvez votre terrain</span><h2>À chaque envie,<br>son mouvement.</h2></div><p>Se renforcer, se dépasser ou souffler.<br>Choisissez ce qui vous fait du bien.</p></div><div class="discipline-grid">${[
    ['01','Musculation encadrée','Les bases solides. Les progrès durables.','strength'],['02','Cycling','Le rythme monte. L’énergie aussi.','cycling'],['03','Mobilité','Bouger mieux, pour aller plus loin.','mobility']
  ].map(([n,name,copy,img])=>`<a href="#/planning?discipline=${encodeURIComponent(name)}" class="discipline-card"><img src="/assets/${img}.jpg" loading="lazy" alt="${e(name)}, photographie sportive d’illustration" width="800" height="650"><span class="discipline-number">${n}</span><div><h3>${name} ${arrow}</h3><p>${copy}</p></div></a>`).join('')}</div><div class="other-disciplines"><span>Et aussi</span>${['HIIT','Circuit training','Coaching individuel'].map(n=>`<a href="${n==='Coaching individuel'?'#/contact?offre=3':`#/planning?discipline=${encodeURIComponent(n)}`}">${n} ↗</a>`).join('')}</div></div></section>
  <section class="section container"><div class="section-heading"><div><span class="eyebrow">Simple, dès le départ</span><h2>Votre objectif.<br>Votre formule.</h2></div><p>Des tarifs clairs, sans engagement caché.<br>Commencez par une séance, tout simplement.</p></div>${offers()}</section>
  <section class="team-teaser container"><img src="/assets/strength.jpg" alt="Sportif s’entraînant dans une salle, illustration de démonstration" loading="lazy" width="800" height="650"><div><span class="eyebrow">L’humain avant la performance</span><h2>On avance mieux<br>bien accompagné.</h2><p>Force, endurance ou mobilité : quatre coachs aux approches complémentaires vous accompagnent à chaque étape.</p><p class="small-print subtle">Une équipe de démonstration au sein d’une entreprise fictive de 20 salariés.</p><a class="button secondary" href="#/salle">Rencontrer l’équipe ${arrow}</a></div></section>
  <section class="section container faq-section"><div><span class="eyebrow">Avant de vous lancer</span><h2>Vous avez<br>des questions ?</h2><a class="text-link" href="#/contact">Parlons-en ${arrow}</a></div>${faq()}</section>
  <section class="visit-banner container"><div><span class="eyebrow">On se retrouve à la salle</span><h2>Faites le premier pas.</h2><p>${e(data.settings.hours)}</p><p class="small-print">Coordonnées fictives à configurer avant publication.</p></div><a class="button" href="#/contact">Informations pratiques ${arrow}</a></section>`;
}
function planning() {
  const query=new URLSearchParams(location.hash.split('?')[1]);
  if(query.has('discipline')) filter.discipline=query.get('discipline');
  const dates=[...new Set(data.classes.map(c=>dateKey(c.starts)))];
  return `${title('TROUVEZ VOTRE<br>PROCHAINE SÉANCE.','Le planning','Un créneau, une envie, et c’est parti. Les disponibilités sont partagées avec l’accueil.')}<section class="container planning-section"><form id="filters" class="filters"><label>Date<select name="date"><option value="">Tous les jours</option>${dates.map(d=>`<option value="${d}" ${filter.date===d?'selected':''}>${date(`${d}T12:00:00Z`,{weekday:'long'})}</option>`).join('')}</select></label><label>Discipline<select name="discipline"><option value="">Toutes les disciplines</option>${data.disciplines.filter(d=>d.name!=='Coaching individuel').map(d=>`<option ${filter.discipline===d.name?'selected':''}>${e(d.name)}</option>`).join('')}</select></label><label>Coach<select name="coach"><option value="">Tous les coachs</option>${data.coaches.map(c=>`<option value="${c.id}" ${String(filter.coach)===String(c.id)?'selected':''}>${e(c.name)}</option>`).join('')}</select></label><button type="button" data-action="reset-filters" class="text-link">Réinitialiser ↺</button></form><div class="list-meta"><span id="result-count" role="status"></span><span>Heure de Paris · Matériel inclus</span></div><div class="session-list" id="planning-results"></div><p class="small-print subtle">Une place réservée est maintenue pendant 10 minutes lors du paiement de démonstration.</p></section>`;
}
function updateResults() {
  const values=Object.fromEntries(new FormData($('#filters')));filter=values;
  const items=data.classes.filter(c=>(!values.date||dateKey(c.starts)===values.date)&&(!values.discipline||c.discipline===values.discipline)&&(!values.coach||c.coach_id===Number(values.coach)));
  $('#result-count').textContent=`${items.length} séance${items.length>1?'s':''} au planning`;
  $('#planning-results').innerHTML=items.length?items.map(c=>sessionRow(c)).join(''):`<div class="empty-state"><h2>Pas de séance sur ce créneau.</h2><p>Essayez une autre date, ou élargissez vos filtres.</p><button class="button secondary" data-action="reset-filters">Voir toutes les séances</button></div>`;
}
function sessionPage(c) {
  const active=c.remaining>0&&c.status!=='cancelled';
  return `<div class="container breadcrumb"><a href="#/planning">← Retour au planning</a></div><section class="container detail-grid"><div><span class="eyebrow">${e(c.level)} · En petit groupe</span><h1>${e(c.discipline).toUpperCase()}</h1><img class="session-photo" src="/assets/${imageMap[c.discipline]||'hero'}.jpg" alt="${e(c.discipline)}, illustration de la discipline" width="800" height="500"><h2>Votre séance, en quelques mots.</h2><p>${e(c.description)}</p><div class="detail-facts"><div><span>Niveau conseillé</span><strong>${e(c.level)}</strong></div><div><span>Durée</span><strong>${c.duration} minutes</strong></div><div><span>Votre coach</span><strong>${e(c.coach)}</strong></div><div><span>À prévoir</span><strong>${e(c.equipment)}</strong></div></div></div><aside class="booking-aside"><span class="eyebrow">Votre prochain rendez-vous</span><h2>${date(c.starts,{weekday:'long'})}</h2><p class="large-time">${time(c.starts)} <span>· ${c.duration} min</span></p>${badge(c)}<div class="price-line"><span>Une personne</span><strong>${euro(c.price)}</strong></div>${active?`<a class="button full" href="#/reserver/${c.id}">Réserver cette séance ${arrow}</a>`:`<button class="button full" disabled>${c.status==='cancelled'?'Séance annulée':'Séance complète'}</button><a class="text-link" href="#/planning">Trouver un autre créneau →</a>`}<p class="small-print">Sans création de compte. Paiement de démonstration.</p><div class="cancellation-note"><strong>Un imprévu ?</strong><p>Annulation et remboursement intégral simulé jusqu’à 24 h avant la séance. Passé ce délai, aucun remboursement.</p><a href="#/conditions">Voir les conditions</a></div></aside></section>`;
}
function steps(current) {return `<ol class="steps">${['La séance','Vos coordonnées','Paiement'].map((label,i)=>`<li class="${i+1===current?'current':i+1<current?'done':''}" ${i+1===current?'aria-current="step"':''}><span>${i+1<current?'✓':i+1}</span>${label}</li>`).join('')}</ol>`;}
function summary(c) {return `<aside class="booking-aside"><span class="eyebrow">Votre séance</span><h2>${e(c.discipline)}</h2><p>${fullDate(c.starts)}<br><strong>${time(c.starts)} · ${c.duration} min</strong></p><p>Avec ${e(c.coach)}</p><div class="price-line"><span>Total TTC · 1 personne</span><strong>${euro(c.price)}</strong></div><p class="small-print">Annulation jusqu’à 24 h avant la séance : remboursement intégral simulé. Passé ce délai : aucun remboursement.</p><a class="small-print" href="#/conditions">Conditions de réservation</a></aside>`;}
function bookingPage(c) {
  if(c.status==='cancelled'||c.remaining<1) return `${title('CE CRÉNEAU N’EST<br>PLUS DISPONIBLE.')}<div class="container section">${notice('Choisissez une autre séance pour continuer.')}<a class="button" href="#/planning">Retour au planning ${arrow}</a></div>`;
  if(attempt?.classId!==c.id) attempt={classId:c.id,key:crypto.randomUUID()};
  return `<section class="container checkout">${steps(2)}<div class="section-heading"><div><a class="back-link" href="#/seance/${c.id}">← Modifier ma séance</a><h1>ON VOUS GARDE<br>UNE PLACE ?</h1><p>Pas besoin de compte. Juste l’essentiel pour votre réservation.</p></div></div><div class="checkout-grid"><form id="participant-form" data-class="${c.id}" class="form-panel">${notice('Démonstration : utilisez uniquement des coordonnées fictives. Aucun e-mail ne sera envoyé.')}<div class="form-error" role="alert" hidden></div><div class="field-grid"><label>Prénom<input name="first_name" autocomplete="given-name" required maxlength="60" value="${e(draft.first_name)}" placeholder="Camille"></label><label>Nom<input name="last_name" autocomplete="family-name" required maxlength="60" value="${e(draft.last_name)}" placeholder="Exemple"></label></div><label>Adresse e-mail<input type="email" name="email" autocomplete="email" required maxlength="254" value="${e(draft.email)}" placeholder="camille@example.test"><small>Votre lien personnel sera affiché après le paiement simulé.</small></label><label>Téléphone <span class="subtle">(facultatif)</span><input type="tel" name="phone" autocomplete="tel" maxlength="30" value="${e(draft.phone)}" placeholder="Facultatif"></label><label class="checkbox"><input type="checkbox" required name="terms"> <span>J’accepte les <a href="#/conditions" target="_blank" rel="noopener">conditions de réservation</a> et comprends qu’il s’agit d’une démonstration.</span></label><button class="button full" type="submit">Continuer vers le paiement ${arrow}</button><p class="small-print subtle">Le total sera rappelé avant de confirmer. Aucune donnée bancaire demandée.</p></form>${summary(c)}</div></section>`;
}
function paymentPage(b) {
  if(b.status==='confirmed') return confirmation(b);
  if(b.status!=='pending') return `<section class="container checkout">${steps(3)}${notice(b.payment_status==='declined'?'Le paiement simulé a été refusé. Aucune réservation n’a été confirmée et la place a été libérée.':'Cette tentative a expiré ou a été annulée. La place a été libérée.','error')}<h1>ON RÉESSAIE ?</h1><p>Vos coordonnées restent disponibles pour une nouvelle tentative.</p><a class="button" href="#/reserver/${b.class_id}" data-retry="true">Revenir à la réservation ${arrow}</a></section>`;
  return `<section class="container checkout">${steps(3)}<div class="section-heading"><div><span class="eyebrow">Dernière étape</span><h1>PRÊT À BOUGER.</h1><p>Vérifiez les informations puis testez le paiement.</p></div></div><div class="checkout-grid"><div class="form-panel"><div class="notice"><strong>Simulateur de paiement</strong><br>En production, cette étape ouvrira la page hébergée du prestataire. Ici, aucun paiement réel, aucune carte bancaire et aucun e-mail envoyé.</div><div class="participant-summary"><h2>Le participant</h2><p>${e(b.first_name)} ${e(b.last_name)}<br>${e(b.email)}</p><p class="small-print">Place maintenue jusqu’à ${time(b.expires)} (heure de Paris).</p></div><form id="payment-form" data-token="${e(b.token)}"><div class="form-error" role="alert" hidden></div><label>Résultat à simuler<select name="outcome"><option value="succeeded">Paiement réussi</option><option value="declined">Paiement refusé</option><option value="pending">Paiement en attente</option></select></label><div class="price-line"><span>Total TTC</span><strong>${euro(b.amount)}</strong></div><button class="button full" type="submit">Simuler le paiement de ${euro(b.amount)} ${arrow}</button></form><button class="text-link cancel-attempt" data-action="cancel-booking" data-token="${e(b.token)}">Abandonner et libérer ma place</button><p class="small-print subtle">Sans action, votre tentative expire au bout de 10 minutes. Aucune confirmation définitive avant le résultat réussi.</p></div>${summary({...b.session,price:b.amount})}</div></section>`;
}
function personalLink(b) {return `${location.origin}/#/reservation/${b.token}`;}
function confirmation(b) {
  const confirmed=b.status==='confirmed', canCancel=(Date.parse(b.session.starts)-Date.now()>=86400000)||b.status==='pending';
  return `<section class="container confirmation"><div class="confirmation-header"><span class="confirmation-mark" aria-hidden="true">${confirmed?'✓':b.status==='pending'?'◷':'↩'}</span><span class="eyebrow">${confirmed?'Votre place vous attend':'Votre réservation'}</span><h1>${confirmed?'C’EST DANS<br>LE PLANNING.':b.status==='pending'?'EN ATTENTE<br>DE PAIEMENT.':'RÉSERVATION<br>'+e(stateLabels[b.status]||b.status).toUpperCase()+'.'}</h1><p>${confirmed?'Réservation confirmée en démonstration. Aucun prélèvement réel n’a été effectué.':'Aucun prélèvement réel. Le statut ci-dessous reflète la simulation.'}</p></div><div class="receipt"><div class="receipt-top"><span>Référence de réservation</span><strong>${e(b.reference)}</strong></div><h2>${e(b.session.discipline)}</h2><p>${fullDate(b.session.starts)} · <strong>${time(b.session.starts)}</strong> · ${b.session.duration} min<br>Avec ${e(b.session.coach)}</p><dl class="receipt-details"><div><dt>Participant</dt><dd>${e(b.first_name)} ${e(b.last_name)}</dd></div><div><dt>E-mail de démonstration</dt><dd>${e(b.email)}</dd></div><div><dt>Réservation</dt><dd>${e(stateLabels[b.status])}</dd></div><div><dt>Paiement</dt><dd>${e(stateLabels[b.payment_status])}</dd></div><div><dt>${b.payment_status==='refunded'?'Remboursement simulé':confirmed?'Montant simulé payé':'Montant de la tentative'}</dt><dd><strong>${euro(b.amount)}</strong></dd></div></dl>${confirmed?`<a class="button full" href="/api/bookings/${b.token}/calendar">Ajouter à mon calendrier <span aria-hidden="true">↓</span></a>`:b.status==='pending'?`<a class="button full" href="#/paiement/${b.token}">Reprendre le paiement simulé ${arrow}</a>`:''}<div class="personal-link"><h3>Votre lien personnel</h3><p>Conservez ce lien pour retrouver votre réservation. Il donne accès à ses informations : gardez-le privé.</p><label>Lien de gestion<input readonly value="${e(personalLink(b))}" aria-label="Lien personnel de gestion"></label><div class="actions"><button class="button secondary small" data-action="copy-link" data-value="${e(personalLink(b))}">Copier le lien</button><button class="text-link" data-action="download-email" data-token="${b.token}">Télécharger la confirmation ↓</button></div><p class="small-print">E-mail non envoyé. Le téléchargement remplace l’envoi pour la démonstration.</p></div>${['pending','confirmed'].includes(b.status)?`<div class="cancellation-note"><h3>Un changement de programme ?</h3><p>${canCancel?'Vous pouvez annuler. Si le paiement a réussi, un remboursement intégral sera simulé et votre place sera libérée.':'Le délai de 24 heures est dépassé : annulation et remboursement indisponibles.'}</p><button class="button secondary full" data-action="cancel-booking" data-token="${b.token}" ${canCancel?'':'disabled'}>${b.status==='pending'?'Abandonner la tentative':'Annuler ma réservation'}</button></div>`:''}<a href="#/planning" class="text-link">Retour au planning ${arrow}</a></div></section>`;
}
function room() {
  return `${title('DE L’ESPACE.<br>DE L’ÉNERGIE.<br>DE L’HUMAIN.','La salle & les coachs','Un plateau pour se renforcer, un studio pour se dépasser, un espace pour récupérer.')}<section class="container room-photo"><img src="/assets/hero.jpg" alt="Équipements de musculation dans une salle, illustration fictive" width="1400" height="800"><span>Votre terrain de progression.</span></section><section class="section container"><div class="section-heading"><h2>Un cadre pour<br>chaque entraînement.</h2><p>Installations présentées à titre de démonstration.<br>Les caractéristiques réelles restent à confirmer.</p></div><div class="facility-list"><article><span>01 / Force</span><h3>Le plateau musculation</h3><p>Poids libres et appareils guidés pour travailler vos mouvements avec un coach.</p></article><article><span>02 / Énergie</span><h3>Le studio collectif</h3><p>Un espace dédié au HIIT, au cycling et aux circuits en petit groupe.</p></article><article><span>03 / Équilibre</span><h3>L’espace mobilité</h3><p>Tapis et petit matériel pour retrouver de l’amplitude et prendre le temps de récupérer.</p></article></div></section><section class="section coaches-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Quatre approches, le même élan</span><h2>Des coachs<br>à vos côtés.</h2></div><p>Profils fictifs de démonstration.<br>Les photos sportives illustrent les disciplines.</p></div><div class="coach-grid">${data.coaches.map((c,i)=>`<article><div class="coach-portrait portrait-${i}"><span>${e(c.initials)}</span><span class="coach-demo">Profil fictif</span></div><span class="eyebrow">${e(c.specialty)}</span><h3>${e(c.name)}</h3><p>${e(c.bio)}</p><a class="text-link" href="#/planning?coach=${c.id}">Ses prochaines séances ${arrow}</a></article>`).join('')}</div></div></section><section class="visit-banner container"><div><h2>À vous de prendre place.</h2><p>Découvrez les disponibilités et choisissez votre premier cours.</p></div><a class="button" href="#/planning">Voir le planning ${arrow}</a></section>`;
}
function contact() {
  const offerId=new URLSearchParams(location.hash.split('?')[1]).get('offre');
  const offer=data.offers.find(o=>String(o.id)===offerId);
  return `${title('ON EN PARLE ?','Contact & informations pratiques','Une question sur une séance ou une formule ? Laissez-nous un message de démonstration.')}<section class="container contact-grid"><form id="contact-form" class="form-panel"><div class="form-error" role="alert" hidden></div>${notice('Coordonnées fictives uniquement. Ce formulaire enregistre votre message en local et n’envoie aucun e-mail.')}<label>Votre nom<input name="name" required minlength="2" maxlength="120" placeholder="Camille Exemple" autocomplete="name"></label><label>Votre e-mail<input name="email" required type="email" maxlength="254" placeholder="camille@example.test" autocomplete="email"></label><label>Objet<input name="subject" required minlength="2" maxlength="120" value="${offer?e(`Renseignements : ${offer.name}`):''}" placeholder="Votre question"></label><label>Votre message<textarea name="message" required minlength="10" maxlength="3000" rows="5" placeholder="Comment pouvons-nous vous aider ?"></textarea></label><label class="honeypot" aria-hidden="true">Votre site<input name="website" tabindex="-1" autocomplete="off"></label><button class="button" type="submit">Enregistrer le message démo ${arrow}</button><p class="small-print">Les données sont conservées dans la base de démonstration. <a href="#/confidentialite">Confidentialité</a></p></form><aside class="contact-details"><span class="eyebrow">Faisons connaissance</span><h2>Rendez-vous<br>à la salle.</h2><dl><div><dt>Horaires de démonstration</dt><dd>${e(data.settings.hours)}</dd></div><div><dt>Adresse</dt><dd>${e(data.settings.address)}</dd></div><div><dt>Téléphone</dt><dd>${e(data.settings.phone)}</dd></div><div><dt>E-mail</dt><dd>${e(data.settings.email)}</dd></div></dl><div class="address-placeholder"><span aria-hidden="true">↗</span><strong>Un lieu à découvrir.</strong><p>L’adresse et le plan d’accès seront ajoutés avant publication.</p></div><p class="small-print subtle">Entreprise fictive. Ne vous déplacez pas : ces informations ne correspondent pas à une salle réelle.</p></aside></section>`;
}
function legal(kind) {
  const pages={
    legal:['Mentions légales',`<h2>Un projet fictif et indépendant</h2><p>Basic IT est une entreprise fictive de 20 salariés, créée pour un projet pédagogique. Il ne vend aucun service réel.</p><h2>Éditeur et hébergeur</h2><p>Raison sociale, forme juridique, siège social, SIREN/RCS, capital, TVA, directeur de publication, coordonnées de l’éditeur et de l’hébergeur : <strong>à compléter avant publication</strong>.</p><h2>Crédits</h2><p>Photographies d’illustration : Unsplash. Typographies Barlow et Barlow Condensed : Google Fonts (SIL Open Font License). Les photos ne représentent ni les coachs fictifs ni une salle exploitée par cette entreprise. Le logotype typographique est propre à ce projet.</p>`],
    confidentialite:['Confidentialité',`<h2>Données de démonstration</h2><p>Utilisez uniquement des identités fictives. Le prénom, le nom, l’e-mail et éventuellement le téléphone servent à illustrer la réservation. Les formulaires de contact et réservations sont enregistrés dans une base SQLite locale, jamais envoyés à un prestataire. Aucune donnée bancaire n’est demandée ni conservée.</p><h2>Accès et conservation</h2><p>Les salariés authentifiés ont accès aux données selon leur profil. Un lien personnel secret donne accès à une seule réservation ; ne le partagez pas. La base persiste jusqu’à sa suppression par l’opérateur. Les sessions salariées expirent après 8 heures.</p><h2>Mesure d’usage</h2><p>Des compteurs agrégés enregistrent les étapes du parcours sans identifiant visiteur ni données de formulaire. Ils ne permettent pas de calculer des visiteurs uniques. Aucune mesure publicitaire ni traceur tiers.</p><h2>Avant publication</h2><p>Responsable du traitement, base légale, durées de conservation, destinataires, transferts, procédure d’exercice des droits, contact RGPD et information sur la réclamation auprès de l’autorité compétente : <strong>à compléter avant publication</strong>. Cette page n’a pas fait l’objet d’une validation juridique.</p>`],
    conditions:['Conditions de réservation',`<h2>Un parcours sans transaction réelle</h2><p>Les prix affichés sont des tarifs de démonstration en euros TTC. Le seul achat en ligne simulé est la séance collective à l’unité. Le carnet de 10 séances et le coaching individuel font l’objet d’une demande de renseignements.</p><h2>Réservation et paiement</h2><p>Une place est bloquée pendant 10 minutes. La réservation reste en attente jusqu’à un paiement simulé réussi. Un refus libère immédiatement la place. Une tentative abandonnée expire après 10 minutes. Réserver une séance passée, complète ou annulée n’est pas possible.</p><h2>Annulation par le participant</h2><p>Jusqu’à 24 heures avant le début : annulation autorisée et remboursement intégral simulé, sans frais. Dans les 24 heures précédant le début : annulation et remboursement indisponibles. Une tentative non payée peut toujours être abandonnée.</p><h2>Annulation par la salle</h2><p>Les réservations d’une séance annulée par un administrateur sont annulées, les places libérées et les paiements réussis marqués remboursés en simulation. Les changements sont visibles via le lien personnel ; aucun e-mail n’est envoyé.</p><h2>Conditions définitives</h2><p>Identité du vendeur, règlement intérieur, assurances, traitement des réclamations, médiation, régime de rétractation applicable, délais réels de remboursement et conditions contractuelles : <strong>à compléter avant publication</strong>. Aucun engagement juridique réel n’est formé dans cette démonstration.</p>`],
    cookies:['Cookies et stockage',`<h2>Le strict nécessaire</h2><p>Le site utilise uniquement un cookie de session salarié HttpOnly et SameSite=Strict, d’une durée maximale de 8 heures. Il est nécessaire à la connexion et supprimé à la déconnexion. Le parcours public ne nécessite aucun cookie.</p><h2>Aucun traceur tiers</h2><p>Les images et les polices sont hébergées localement. Les événements du parcours sont agrégés côté serveur, sans identifiant de visiteur. Aucun cookie publicitaire ou d’analyse tiers n’est installé ; aucune bannière de consentement facultatif n’est donc affichée dans cette version.</p><p>L’inventaire et les obligations de consentement devront être réévalués si des services externes sont ajoutés.</p>`]
  };
  const [heading,body]=pages[kind];return `${title(e(heading).toUpperCase(),'Informations du projet')}<article class="container legal-copy">${notice('Document de démonstration. Informations à compléter avant publication ; aucune validation juridique revendiquée.')} ${body}<a class="button secondary" href="#/">Retour à l’accueil</a></article>`;
}
function login() {
  return `<section class="container login-layout"><div><span class="eyebrow">Côté équipe</span><h1>LE MOUVEMENT,<br>ÇA S’ORGANISE.</h1><p>Un planning commun. Des places à jour.<br>Et votre équipe, au même endroit.</p><div class="login-art" aria-hidden="true">↗</div></div><form id="login-form" class="form-panel"><h2>Espace salarié</h2><p>Connexion protégée côté serveur. Comptes de test uniquement.</p><div class="form-error" role="alert" hidden></div><label>Adresse e-mail<input type="email" name="email" autocomplete="username" required value="admin@basic-it.test"></label><label>Mot de passe<input type="password" name="password" autocomplete="current-password" required></label><button class="button full" type="submit">Se connecter ${arrow}</button><details class="demo-accounts"><summary>Accès de démonstration</summary><p><strong>Mot de passe commun</strong><br>DemoSport2027!</p><p>admin@basic-it.test<br>accueil@basic-it.test<br>coach@basic-it.test (Alex)</p><p>Ces comptes publics sont réservés au test local et doivent être supprimés avant production.</p></details><a class="text-link" href="#/retrouver">Retrouver une réservation personnelle →</a></form></section>`;
}
function findBooking() {return `${title('VOTRE RÉSERVATION,<br>À PORTÉE DE LIEN.','Gestion de réservation','Collez le lien personnel conservé lors de la confirmation.')}<section class="container narrow section"><form id="find-form" class="form-panel"><div class="form-error" role="alert" hidden></div><label>Lien personnel<input type="text" name="link" required placeholder="http://localhost:3000/#/reservation/…"></label><button class="button" type="submit">Retrouver ma réservation ${arrow}</button><p class="small-print">Aucune recherche publique par e-mail, pour protéger les informations des participants.</p></form></section>`;}

// Espace salarié : les contrôles de visibilité complètent les autorisations du serveur.
function dashboard() {
  const u=staff.user, allBookings=staff.bookings, confirmed=allBookings.filter(b=>b.status==='confirmed');
  const tabs=[['dashboard','Vue d’ensemble'],['sessions','Séances'],['bookings','Réservations'],...(u.role==='admin'?[['employees','Salariés'],['offers','Offres'],['settings','Paramètres']]:[])];
  if(!tabs.some(t=>t[0]===staffTab))staffTab='dashboard';
  return `<section class="staff-shell container"><div class="staff-top"><div><span class="eyebrow">Espace salarié · ${e(roleLabels[u.role])}</span><h1>BONJOUR, ${e(u.name.split(' ')[0]).toUpperCase()}<span class="lime-text">.</span></h1><p>Données de démonstration · ${u.role==='coach'?'Vos séances et leurs participants.':'Réservations en ligne et accueil, un seul planning.'}</p></div><button class="button secondary small" data-action="logout">Se déconnecter ↗</button></div><nav class="staff-tabs" aria-label="Rubriques de l’espace salarié">${tabs.map(([id,label])=>`<button class="${staffTab===id?'selected':''}" data-action="staff-tab" data-tab="${id}" ${staffTab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div id="staff-content">${staffTab==='dashboard'?`<div class="dashboard-stats"><article><span>En ligne · confirmées</span><strong>${confirmed.filter(b=>b.source==='online').length}</strong></article><article><span>Accueil · confirmées</span><strong>${confirmed.filter(b=>b.source==='accueil').length}</strong></article><article><span>Paiements réussis simulés</span><strong>${allBookings.filter(b=>b.payment_status==='succeeded').length}</strong></article><article><span>Présences renseignées</span><strong>${confirmed.filter(b=>b.attended).length}</strong></article></div><div class="dashboard-section"><div class="section-heading"><h2>Les prochains rendez-vous</h2><button class="text-link" data-action="staff-tab" data-tab="sessions">Toutes les séances ↗</button></div>${staff.classes.filter(c=>Date.parse(c.starts)>Date.now()).slice(0,5).map(c=>`<div class="staff-session-line"><div><strong>${e(c.discipline)}</strong><span>${date(c.starts)} · ${time(c.starts)} · ${e(c.coach)}</span></div>${badge(c)}<button class="button secondary small" data-action="participants" data-class="${c.id}">Participants →</button></div>`).join('')}</div>${u.role==='admin'?analytics():''}`:staffTab==='sessions'?staffSessions():staffTab==='bookings'?staffBookings():staffTab==='employees'?staffEmployees():staffTab==='offers'?staffOffers():staffSettings()}</div></section>`;
}
function analytics() {
  const groups=new Map();for(const b of staff.bookings.filter(b=>b.status==='confirmed'))groups.set(b.email,(groups.get(b.email)||0)+1);
  const events={planning_viewed:'Consultations du planning',class_viewed:'Consultations d’une séance',booking_started:'Réservations commencées',payment_started:'Paiements commencés',payment_confirmed:'Paiements confirmés',booking_cancelled:'Annulations'};
  return `<div class="analytics-grid"><section class="dashboard-section"><h2>Le parcours, en chiffres</h2><p class="small-print subtle">Événements agrégés depuis l’installation. Les réservations préchargées ne génèrent pas d’événements.</p><dl class="metric-list">${Object.entries(events).map(([id,label])=>`<div><dt>${label}</dt><dd>${staff.events.find(v=>v.type===id)?.count||0}</dd></div>`).join('')}</dl></section><section class="dashboard-section"><h2>Pour bien lire ces chiffres</h2><p>${groups.size} e-mails distincts dans les réservations confirmées, dont ${[...groups.values()].filter(v=>v>1).length} associés à plusieurs séances.</p><p>Un e-mail ne prouve ni une identité ni un nouveau client. Le statut « nouveau client » reste indéterminé sans historique complet. Une réservation en ligne n’est pas nécessairement un client supplémentaire.</p><p><strong>${e(staff.settings.missed_calls)} appels manqués</strong> renseignés manuellement. Aucune intégration téléphonique.</p></section></div>${staff.messages.length?`<section class="dashboard-section"><h2>Messages de démonstration</h2>${staff.messages.map(m=>`<details class="message-item"><summary>${e(m.subject)} · ${e(m.name)}</summary><p>${e(m.email)}</p><p>${e(m.message)}</p></details>`).join('')}</section>`:''}`;
}
function staffSessions() {
  return `<div class="section-heading"><h2>Le planning de l’équipe</h2>${staff.user.role==='admin'?'<button class="button small" data-action="new-session">Créer une séance +</button>':''}</div><div id="session-editor"></div><div class="table-wrap"><table><caption class="sr-only">Séances de démonstration</caption><thead><tr><th>Séance</th><th>Date · Paris</th><th>Coach</th><th>Places</th><th>Actions</th></tr></thead><tbody>${staff.classes.map(c=>`<tr><td><strong>${e(c.discipline)}</strong><br><span class="subtle">${c.duration} min · ${euro(c.price)}</span></td><td>${date(c.starts)}<br>${time(c.starts)}</td><td>${e(c.coach)}</td><td>${badge(c)}</td><td><div class="table-actions"><button class="text-link" data-action="participants" data-class="${c.id}">Participants</button>${staff.user.role==='admin'&&Date.parse(c.starts)>Date.now()?`<button class="text-link" data-action="edit-session" data-class="${c.id}">Modifier</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;
}
function staffBookings() {
  return `<div class="section-heading"><h2>Réservations & présences</h2>${staff.user.role!=='coach'?'<div class="actions"><a class="button secondary small" href="/api/staff/export">Exporter CSV ↓</a><button class="button small" data-action="new-booking">Réserver à l’accueil +</button></div>':''}</div><div id="frontdesk-editor"></div><div class="search-row"><label>Rechercher un participant<input type="search" id="booking-search" placeholder="Nom, e-mail ou référence…"></label><label>Séance<select id="booking-class"><option value="">Toutes les séances</option>${staff.classes.map(c=>`<option value="${c.id}">${e(c.discipline)} · ${date(c.starts)} ${time(c.starts)}</option>`).join('')}</select></label></div><p id="booking-count" class="small-print" role="status"></p><div class="table-wrap"><table><caption class="sr-only">Réservations de démonstration et présences</caption><thead><tr><th>Participant</th><th>Séance</th><th>Origine</th><th>Réservation / paiement</th><th>Présence</th><th>Action</th></tr></thead><tbody id="booking-rows"></tbody></table></div>`;
}
function updateBookingRows() {
  const search=$('#booking-search').value.trim().toLowerCase(),classId=$('#booking-class').value;
  const rows=staff.bookings.filter(b=>(!classId||b.class_id===+classId)&&`${b.first_name} ${b.last_name} ${b.email} ${b.reference}`.toLowerCase().includes(search));
  $('#booking-count').textContent=`${rows.length} réservation${rows.length>1?'s':''}`;
  $('#booking-rows').innerHTML=rows.length?rows.map(b=>`<tr><td><strong>${e(b.first_name)} ${e(b.last_name)}</strong><br>${e(b.email)}<br><span class="subtle small-print">${e(b.reference)}</span></td><td>${e(b.discipline)}<br>${date(b.starts)} · ${time(b.starts)}</td><td>${b.source==='online'?'En ligne':'Accueil'}</td><td><span class="badge ${b.status==='confirmed'?'':'muted'}">${e(stateLabels[b.status])}</span><br><span class="small-print">${e(stateLabels[b.payment_status])}</span></td><td><label class="checkbox"><input type="checkbox" data-attendance="${b.id}" ${b.attended?'checked':''} ${b.status!=='confirmed'?'disabled':''} aria-label="Présence de ${e(b.first_name)} ${e(b.last_name)}"> Présent</label></td><td>${staff.user.role!=='coach'&&(b.status==='pending'||(b.status==='confirmed'&&Date.parse(b.starts)-Date.now()>=86400000))?`<button class="text-link" data-action="staff-cancel" data-id="${b.id}">Annuler</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="6">Aucun participant ne correspond à votre recherche.</td></tr>';
}
function sessionEditor(c) {
  const value=c?dateKey(c.starts)+'T'+time(c.starts).replace(' h ',':'):'';
  return `<form id="session-form" class="form-panel editor" data-id="${c?.id||''}"><div class="section-heading"><h2>${c?'Modifier la séance':'Nouvelle séance'}</h2><button class="text-link" type="button" data-action="close-editor">Fermer ×</button></div><div class="form-error" role="alert" hidden></div><div class="field-grid"><label>Discipline<select name="discipline">${data.disciplines.map(d=>`<option ${c?.discipline===d.name?'selected':''}>${e(d.name)}</option>`).join('')}</select></label><label>Date et heure (Paris)<input type="datetime-local" name="starts" value="${value}" required></label><label>Coach<select name="coach_id">${data.coaches.map(co=>`<option value="${co.id}" ${c?.coach_id===co.id?'selected':''}>${e(co.name)}</option>`).join('')}</select></label><label>Capacité<input type="number" name="capacity" min="1" max="100" value="${c?.capacity||12}" required></label><label>Durée (minutes)<input type="number" name="duration" min="15" max="180" value="${c?.duration||60}" required></label><label>Prix (€ TTC)<input type="number" name="price" min="1" max="1000" step="0.01" value="${c?c.price/100:15}" required></label><label>Statut<select name="status"><option value="available" ${c?.status==='available'?'selected':''}>Disponible</option><option value="cancelled" ${c?.status==='cancelled'?'selected':''}>Annulée</option></select></label></div><p class="small-print">Annuler une séance annule ses réservations et simule le remboursement des paiements réussis. Toute modification sera visible via le lien personnel, sans e-mail envoyé.</p><button class="button" type="submit">${c?'Enregistrer les modifications':'Créer la séance'} ${arrow}</button></form>`;
}
function frontdeskEditor() {
  return `<form id="frontdesk-form" class="form-panel editor"><div class="section-heading"><h2>Réservation à l’accueil</h2><button class="text-link" type="button" data-action="close-editor">Fermer ×</button></div>${notice('Identités fictives uniquement. Le stock est partagé avec les réservations en ligne.')}<div class="form-error" role="alert" hidden></div><label>Séance<select name="class_id">${staff.classes.filter(c=>c.remaining>0&&c.status!=='cancelled'&&Date.parse(c.starts)>Date.now()&&c.discipline!=='Coaching individuel').map(c=>`<option value="${c.id}">${e(c.discipline)} · ${date(c.starts)} ${time(c.starts)} · ${c.remaining} places · ${euro(c.price)}</option>`).join('')}</select></label><div class="field-grid"><label>Prénom<input name="first_name" required maxlength="60"></label><label>Nom<input name="last_name" required maxlength="60"></label></div><label>E-mail<input type="email" name="email" required placeholder="camille@example.test"></label><label>Paiement<select name="payment_status"><option value="succeeded">Simuler un paiement réussi à l’accueil</option><option value="pending">En attente (place bloquée 10 minutes)</option></select></label><button class="button" type="submit">Enregistrer la réservation ${arrow}</button></form>`;
}
