  return `<h2>Paramètres de la salle</h2><form id="settings-form" class="form-panel editor"><div class="form-error" role="alert" hidden></div>${notice('Ces informations apparaissent sur le site. Elles restent identifiées comme fictives dans la démonstration.')} ${[['address','Adresse'],['phone','Téléphone'],['email','E-mail'],['hours','Horaires']].map(([id,label])=>`<label>${label}<input name="${id}" required maxlength="500" value="${e(staff.settings[id])}"></label>`).join('')}<label>Appels manqués (saisie manuelle)<input name="missed_calls" type="number" min="0" max="999999" required value="${e(staff.settings.missed_calls)}"></label><button class="button" type="submit">Enregistrer les paramètres ${arrow}</button></form>`;
