async function refreshStaff(message) {staff=await api('/api/staff');data=await api('/api/public');main.innerHTML=dashboard();if(staffTab==='bookings')updateBookingRows();if(message)toast(message);}
// datetime-local est exprimé en Europe/Paris, indépendamment du fuseau du navigateur.
function parisToUTC(value) {
  const [ymd,hm]=value.split('T');let t=Date.parse(ymd+'T'+hm+':00Z');const target=t;
  for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(t).map(p=>[p.type,p.value]));t+=target-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);}
  if(dateKey(t)+'T'+time(t)!==value)throw new Error('Cette heure n’existe pas lors du changement d’heure à Paris. Choisissez un autre horaire.');
  return new Date(t).toISOString();
}
async function route() {
  const version=++routeVersion;
  const path=(location.hash.slice(1)||'/').split('?')[0], parts=path.split('/').filter(Boolean),page=parts[0]||'home';
  $('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');
  $$('#navigation a').forEach(a=>{const active=a.dataset.nav===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  main.setAttribute('aria-busy','true');main.innerHTML=loading();
  try {
    data=await api('/api/public'); if(version!==routeVersion)return;
    let html;
    if(page==='home')html=home();
    else if(page==='offres')html=`${title('LE BON ÉLAN.<br>AU BON PRIX.','Offres & tarifs','Une séance pour essayer, un carnet pour continuer, un coach pour vos objectifs.')}<section class="container offers-page">${offers()}</section><section class="section container faq-section"><h2>Tout est clair ?</h2>${faq()}</section>`;
    else if(page==='planning') {if(new URLSearchParams(location.hash.split('?')[1]).has('coach'))filter.coach=new URLSearchParams(location.hash.split('?')[1]).get('coach');html=planning();track('planning_viewed');}
    else if(page==='seance'||page==='reserver') {const c=data.classes.find(c=>c.id===+parts[1]);if(!c)throw new Error('Cette séance est introuvable ou passée. Consultez le planning pour choisir un autre créneau.');html=page==='seance'?sessionPage(c):bookingPage(c);if(page==='seance')track('class_viewed');}
    else if(page==='paiement'||page==='reservation') {const b=await api(`/api/bookings/${encodeURIComponent(parts[1])}`);if(version!==routeVersion)return;html=page==='paiement'?paymentPage(b):confirmation(b);if(page==='paiement'&&b.status==='pending')track('payment_started');draft={first_name:b.first_name,last_name:b.last_name,email:b.email,phone:b.phone};if(b.status!=='pending')attempt=null;}
    else if(page==='salle')html=room();
    else if(page==='contact')html=contact();
    else if(['legal','confidentialite','conditions','cookies'].includes(page))html=legal(page);
    else if(page==='retrouver')html=findBooking();
    else if(page==='salaries') {try {staff=await api('/api/staff');html=dashboard();}catch {staff=null;html=login();}}
    else throw new Error('Cette page n’existe pas. Retrouvez les séances dans le planning.');
    if(version!==routeVersion)return;main.innerHTML=html;
    if(page==='planning')updateResults();if(page==='salaries'&&staff&&staffTab==='bookings')updateBookingRows();
    const names={home:'Votre prochain mouvement',planning:'Planning & réservation',offres:'Offres & tarifs',seance:'Votre séance',reserver:'Vos coordonnées',paiement:'Paiement de démonstration',reservation:'Votre réservation',salle:'La salle & les coachs',contact:'Contact',salaries:'Espace salarié'};
    document.title=`${names[page]||'Informations'} · Basic IT`;
    window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
  }catch(error) {if(version===routeVersion)main.innerHTML=`${title('UNE PETITE PAUSE.')}<section class="container section">${notice(e(error.message),'error')}<div class="actions"><a class="button" href="#/planning">Voir le planning ${arrow}</a><button class="button secondary" data-action="reload">Réessayer</button></div></section>`;}
  finally {if(version===routeVersion)main.removeAttribute('aria-busy');}
}
document.addEventListener('submit',async event=>{
  const form=event.target;if(form.closest('dialog')||form.id==='filters')return;event.preventDefault();
  if(form.dataset.busy)return;form.dataset.busy='true';const button=$('button[type="submit"]',form),original=button?.innerHTML;if(button){button.disabled=true;button.textContent='En cours…';}
  const errorBox=$('.form-error',form);if(errorBox)errorBox.hidden=true;
  const body=Object.fromEntries(new FormData(form));
  try {
    if(form.id==='participant-form') {draft=body;const b=await post('/api/bookings',{...body,class_id:Number(form.dataset.class),idempotency:attempt.key});location.hash=`/paiement/${b.token}`;}
    else if(form.id==='payment-form') {const b=await post(`/api/bookings/${form.dataset.token}/pay`,body);if(b.payment_status==='pending')toast('Paiement toujours en attente. Aucune réservation confirmée. Vous pouvez choisir un autre résultat ou abandonner.');else if(b.status==='confirmed')location.hash=`/reservation/${b.token}`;else{attempt=null;await route();}}
    else if(form.id==='contact-form') {const result=await post('/api/contact',body);form.reset();toast(result.message);form.prepend(Object.assign(document.createElement('p'),{className:'notice',textContent:result.message}));}
    else if(form.id==='login-form'){await post('/api/login',body);staffTab='dashboard';await route();toast('Connexion réussie à l’espace de démonstration.');}
    else if(form.id==='find-form'){const match=body.link.match(/(?:reservation|paiement)\/([\w-]{43})(?:$|[?#])/);if(!match)throw new Error('Collez le lien personnel complet affiché sur votre confirmation.');await api('/api/bookings/'+match[1]);location.hash='/reservation/'+match[1];}
    else if(form.id==='frontdesk-form') {if(!form.dataset.key)form.dataset.key=crypto.randomUUID();const b=await post('/api/staff/bookings',{...body,idempotency:form.dataset.key});await refreshStaff('Réservation accueil enregistrée. Le stock en ligne est à jour.');$('#frontdesk-editor').innerHTML=notice(`Réservation ${e(b.reference)} enregistrée (${e(stateLabels[b.status])}). <a href="#/reservation/${b.token}">Ouvrir sa confirmation et son lien personnel →</a>`);toast('Le stock est à jour sur le site et à l’accueil.');}
    else if(form.id==='session-form') {body.starts=parisToUTC(body.starts);body.price=Math.round(Number(body.price)*100);if(form.dataset.id&&!await confirmAction('Modifier cette séance ? Les participants verront les changements via leur lien personnel. Annuler la séance simulera le remboursement des paiements réussis.'))return;if(form.dataset.id)await patch('/api/staff/classes/'+form.dataset.id,body);else await post('/api/staff/classes',body);await refreshStaff('Séance enregistrée. Les disponibilités sont à jour.');}
    else if(form.id==='employee-form') {await post('/api/staff/employees',body);await refreshStaff('Compte salarié créé.');}
    else if(form.classList.contains('employee-update')) {if(!await confirmAction('Modifier ce compte et fermer ses sessions en cours ?'))return;await patch('/api/staff/employees/'+form.dataset.id,{...body,active:body.active==='on'});await refreshStaff('Accès salarié mis à jour.');}
    else if(form.classList.contains('offer-form')) {if(!await confirmAction('Enregistrer ces changements dans les offres publiques ? Les séances existantes garderont leur propre tarif.'))return;await patch('/api/staff/offers/'+form.dataset.id,{...body,price:Math.round(Number(body.price)*100)});await refreshStaff('Offre mise à jour.');}
    else if(form.id==='settings-form') {if(!await confirmAction('Mettre à jour les informations de la salle affichées publiquement ?'))return;await patch('/api/staff/settings',body);await refreshStaff('Paramètres enregistrés.');}
  }catch(error){if(errorBox){errorBox.textContent=error.message;errorBox.hidden=false;errorBox.scrollIntoView({block:'nearest'});}else toast(error.message);}
  finally{delete form.dataset.busy;if(button){button.disabled=false;button.innerHTML=original;}}
});
document.addEventListener('click',async event=>{
  const menu=event.target.closest('.menu-toggle');if(menu){const open=$('#navigation').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));return;}
  const button=event.target.closest('[data-action]');if(!button)return;
  const action=button.dataset.action;
  try{
    if(action==='reset-filters'){filter={date:'',discipline:'',coach:''};$$('#filters select').forEach(s=>s.value='');history.replaceState(null,'','#/planning');updateResults();}
    else if(action==='reload')await route();
    else if(action==='copy-link'){try{await navigator.clipboard.writeText(button.dataset.value);toast('Lien personnel copié. Conservez-le à l’abri.');}catch{const input=$('.personal-link input');input.select();toast('Sélectionnez puis copiez le lien personnel.');}}
    else if(action==='download-email'){const b=await api('/api/bookings/'+button.dataset.token);const content=`CONFIRMATION DE DÉMONSTRATION - AUCUN PAIEMENT RÉEL\n\nRéférence : ${b.reference}\nSéance : ${b.session.discipline}\n${fullDate(b.session.starts)} à ${time(b.session.starts)} (Paris)\nParticipant : ${b.first_name} ${b.last_name}\nMontant simulé : ${euro(b.amount)}\nRéservation : ${stateLabels[b.status]}\nPaiement : ${stateLabels[b.payment_status]}\n\nLien personnel secret : ${personalLink(b)}\n\nAnnulation possible jusqu’à 24 heures avant la séance, remboursement intégral simulé. Aucun e-mail envoyé.\n`;download(content,`confirmation-${b.reference}.txt`,'text/plain;charset=utf-8');}
    else if(action==='cancel-booking'){if(!await confirmAction('Annuler cette réservation ? La place sera libérée. Tout paiement réussi sera remboursé en simulation uniquement.'))return;button.disabled=true;await post('/api/bookings/'+button.dataset.token+'/cancel');location.hash='/reservation/'+button.dataset.token;await route();toast('Réservation annulée. Place libérée, remboursement simulé si applicable.');}
    else if(action==='logout'){await post('/api/logout');staff=null;await route();toast('Vous êtes déconnecté.');}
    else if(action==='staff-tab'){staffTab=button.dataset.tab;await refreshStaff();}
    else if(action==='participants'){staffTab='bookings';await refreshStaff();$('#booking-class').value=button.dataset.class;updateBookingRows();$('#booking-search').focus();}
    else if(action==='new-session'||action==='edit-session'){const c=staff.classes.find(c=>c.id===Number(button.dataset.class));$('#session-editor').innerHTML=sessionEditor(c);$('#session-editor').scrollIntoView({block:'start'});$('#session-form select').focus({preventScroll:true});}
    else if(action==='close-editor'){button.closest('.editor').remove();}
    else if(action==='new-booking'){$('#frontdesk-editor').innerHTML=frontdeskEditor();$('#frontdesk-editor').scrollIntoView({block:'start'});$('#frontdesk-form select').focus({preventScroll:true});}
    else if(action==='staff-cancel'){if(!await confirmAction('Annuler cette réservation et simuler son remboursement intégral ?'))return;await post('/api/staff/bookings/'+button.dataset.id+'/cancel');await refreshStaff('Réservation annulée et place libérée.');}
  }catch(error){toast(error.message);button.disabled=false;}
});
document.addEventListener('change',async event=>{
  if(event.target.closest('#filters'))updateResults();
  if(event.target.id==='booking-class')updateBookingRows();
  if(event.target.matches('[data-attendance]')){const box=event.target;box.disabled=true;try{await post(`/api/staff/bookings/${box.dataset.attendance}/attendance`,{attended:box.checked});toast('Présence enregistrée.');}catch(error){box.checked=!box.checked;toast(error.message);}finally{box.disabled=false;}}
});
document.addEventListener('input',event=>{if(event.target.id==='booking-search')updateBookingRows();if(event.target.closest('#participant-form'))draft=Object.fromEntries(new FormData($('#participant-form')));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}});
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#year').textContent=new Date().getFullYear();
window.addEventListener('hashchange',route);
route();
